            "reason": reason,
            "iterations": self.iteration_count
        })

        return {
            "goal": goal,
            "status": "failed",
            "reason": reason,
            "iterations": self.iteration_count,
            "evidence_log": self.evidence_logger.get_log_path() if hasattr(self.evidence_logger, 'get_log_path') else None
