    def handle_validator_feedback(self, feedback_type: str, data: dict) -> dict:
        """
        Convert validator feedback into research constraints for next iteration.

        Args:
            feedback_type: Type of feedback ("false_positive", "low_impact", "duplicate")
            data: Feedback data including which vector/hypothesis was problematic

        Returns:
            Updated constraints dictionary
        """
        constraints = {}

        if feedback_type == "false_positive":
            # Mark this vector as producing false positives
            constraints["exclude_vectors"] = [data.get("vector")]
            self._log_evidence("hypothesis_rejected", {
                "reason": "false_positive",
                "vector": data.get("vector"),
                "hypothesis": data.get("hypothesis"),
            })

        elif feedback_type == "low_impact":
            # Mark as low impact, deprioritize but don't exclude
            constraints["low_impact_vectors"] = [data.get("vector")]
            self._log_evidence("hypothesis_rejected", {
                "reason": "low_impact",
                "vector": data.get("vector"),
                "hypothesis": data.get("hypothesis"),
            })

        elif feedback_type == "duplicate":
            # This finding is duplicate, move to next vector
            constraints["exclude_vectors"] = [data.get("vector")]
            self._log_evidence("hypothesis_rejected", {
                "reason": "duplicate",
                "vector": data.get("vector"),
                "hypothesis": data.get("hypothesis"),
            })

        elif feedback_type == "promising":
            # This hypothesis is promising, promote it
            self._log_evidence("hypothesis_promoted", {
                "vector": data.get("vector"),
                "hypothesis": data.get("hypothesis"),
                "confidence": data.get("confidence", 0.0),
            })

        return constraints

def _norm(text: str) -> str:
    """Minimal Hungarian accent-stripping normalization for heuristic checks."""
    MAP = str.maketrans("áéíóöőúüűÁÉÍÓÖŐÚÜŰ", "aeiooouuuAEIOOOUUU")
    return text.lower().translate(MAP)

def _polish_direct_lightweight(raw: str, prompt: str) -> str:
    """Polish DIRECT_LIGHTWEIGHT_RESPONSE.

    Primary rule: if prompt requests an exact format (N lines, N sentences,
    bullet prefix), return the raw content unchanged except for trailing whitespace.
    The formatter is not allowed to add footers, summaries, or extra lines that
    would break the requested structure.
    """
    norm = _norm(prompt)

    # Exact line count — do not touch
    if re.search(r"pontosan\s+\d+\s+sor", norm):
        return raw.strip()

    # Exact sentence count — do not touch
    if re.search(r"(\d+)\s+(?:rovid\s+)?mondat", norm):
        return raw.strip()

    # Bullet prefix requested — do not touch
    if re.search(r"kotojel|kotojellel|kotojeles", norm):
        return raw.strip()

    # Generic DL: only strip whitespace
    return raw.strip()


